css:
.d-pal{position:absolute;inset:auto;left:50%;top:12px;transform:translateX(-50%);width:260px;background:var(--paper);border:1px solid var(--line);border-radius:10px;box-shadow:0 18px 40px #20241e22;padding:8px;z-index:5}
.d-pal input{width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;color:inherit;font:inherit;font-size:12px;padding:6px;outline:none}
.d-pal .d-palette-list{margin-top:6px;display:flex;flex-direction:column}
.d-pal .d-palette-list span{padding:6px 8px;border-radius:6px;font-size:11.5px;color:var(--muted)}
.d-pal .d-palette-list span.sel{background:color-mix(in srgb,var(--ink) 8%,transparent);color:var(--ink)}
.d-btn{font:inherit;font-size:13px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;transition:transform .16s var(--ease),background-color .16s,color .16s,border-color .16s}
.d-btn:hover{box-shadow:0 6px 18px #20241e14}
.d-btn:active{transform:scale(.97)}

init:
root => {
    const btn = root.querySelector('[data-pal]'), pal = root.querySelector('.d-pal'), inp = pal.querySelector('input'), list = pal.querySelector('.d-palette-list');
    const items = ['新建项目', '导出资源', '打开设置', '切换主题', '搜索页面'];
    const render = () => { list.innerHTML = items.filter(x => !inp.value || x.includes(inp.value)).map((x, i) => `<span class="${i === 0 ? 'sel' : ''}">${x}</span>`).join(''); };
    btn.onclick = () => { pal.hidden = !pal.hidden; if (!pal.hidden) { inp.value = ''; render(); inp.focus(); } };
    inp.oninput = render;
    inp.onkeydown = e => { if (e.key === 'Escape') pal.hidden = true; };
  }
